class Solution:
    def word_break(self, s: str, word_dict: list[str]) -> bool:
        word_set = set(word_dict)
        memo = {}

        def dfs(i):
            if i == len(s):
                return True
            if i in memo:
                return memo[i]

            for j in range(i + 1, len(s) + 1):
                if s[i:j] in word_set and dfs(j):
                    memo[i] = True
                    return True

            memo[i] = False
            return False

        return dfs(0)

