class Solution:
    def minimum_xor_sum(self, nums1: list[int], nums2: list[int]) -> int:
        n = len(nums1)
        memo = {}

        def dfs(i, mask):
            if i == n:
                return 0
            if mask in memo:
                return memo[mask]

            res = float('inf')
            for j in range(n):
                if not (mask & (1 << j)):
                    res = min(res, (nums1[i] ^ nums2[j]) + dfs(i + 1, mask | (1 << j)))

            memo[mask] = res
            return res

        return dfs(0, 0)

